import { useState, useContext } from "react";
import { AuthContext } from "../context/AuthContext";
import "../styles/auth.css";

function Login() {
  const { login } = useContext(AuthContext);
  const [role, setRole] = useState(null);
  const [show, setShow] = useState(false);
  const [success, setSuccess] = useState(false);

  /* ⭐ ROLE SELECTION SCREEN */
  if (!role) {
    return (
      <div className="split">
        <div className="left" onClick={() => setRole("citizen")}>
          <div className="role-card">
            <h1>Citizen</h1>
            <p>Report civic issues easily</p>
          </div>
        </div>

        <div className="right" onClick={() => setRole("admin")}>
          <div className="role-card">
            <h1>Authority</h1>
            <p>Manage complaints efficiently</p>
          </div>
        </div>
      </div>
    );
  }

  /* ⭐ LOGIN SUCCESS ANIMATION */
  if (success) {
    return (
      <div className="auth success">
        <h1>Welcome 🎉</h1>
      </div>
    );
  }

  /* ⭐ LOGIN FORM */
  return (
    <div className={`auth ${role}`}>
      <div className="auth-card">
        <h2>{role === "citizen" ? "Citizen Login" : "Authority Login"}</h2>

        {/* ⭐ SOCIAL UI */}
        <div className="social">
          <div>G</div>
          <div>F</div>
          <div></div>
        </div>

        <input placeholder="Email" />

        <input
          type={show ? "text" : "password"}
          placeholder="Password"
        />

        <p className="toggle" onClick={() => setShow(!show)}>
          {show ? "Hide Password" : "Show Password"}
        </p>

        <button
          onClick={() => {
            setSuccess(true);
            setTimeout(() => login(role), 1200);
          }}
        >
          Login
        </button>

        <p className="back" onClick={() => setRole(null)}>
          ← Change Role
        </p>
      </div>
    </div>
  );
}

export default Login;
